from moler.cmd.commandchangingprompt import CommandChangingPrompt
from moler.exceptions import CommandFailure
import re

__author__ = 'Dariusz Rosinski'
__copyright__ = 'Copyright (C) 2021, Nokia'
__email__ = 'dariusz.rosinski@nokia.com'


class Fsp(CommandChangingPrompt):
    """Command for exiting DSP on RTG."""

    abia_mapping_string = """
1a/b/c/d - ABIA 1 left side
2a/b/c/d - ABIA 2 left side
3a/b/c/d - ABIA 3 left side
5a/b/c/d - ABIA 4 right side
6a/b/c/d - ABIA 5 right side
7a/b/c/d - ABIA 6 right side"""
    _re_error_not_connected_abia = re.compile(r"ssh: connect to host fsp-\w+ port \d+: No route to host")
    _re_wrong_rack_side = re.compile(r"Could not resolve hostname fsp-\w+: Temporary failure in name resolution")

    def __init__(self, connection, fsp_number, expected_prompt=None, prompt=None, newline_chars=None, runner=None):
        """
        Fsp command for state transitoin to FSP.

        :param connection: moler connection to device, terminal when command is executed.
        :param fsp_number: number of fsp in format [1-3][abcd]|[5-7][abcd] example 1b or 6d
        :param expected_prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(Fsp, self).__init__(connection, prompt=prompt, expected_prompt=expected_prompt,
                                  newline_chars=newline_chars, runner=runner)

        self.fsp_number = fsp_number
        self.ret_required = False
        self._cmd_output_started = True

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return f"fsp-{self.fsp_number}"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            self._error_wrong_rack_side(line)
            self._error_no_abia_connected(line)
        return super(Fsp, self).on_new_line(line, is_full_line)

    def _error_wrong_rack_side(self, line):
        if re.search(self._re_wrong_rack_side, line):
            error_message = "You are trying to connect ABIA from wrong rack side. Go to another side and try again." + \
                            self.abia_mapping_string
            raise CommandFailure(command=self, message=error_message)

    def _error_no_abia_connected(self, line):
        if re.search(self._re_error_not_connected_abia, line):
            error_message = "ABIA you are trying to connect is not present or connection failure occured." + \
                            self.abia_mapping_string
            raise CommandFailure(command=self, message=error_message)


